/// Packet `packet.CommandBlockUpdate` (ID 78), sent by the client and the server.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct CommandBlockUpdate {
    /// The block. Wire form: `Bool`.
    pub block: bool,
    /// The position. Wire form: `BlockPos`.
    pub position: BlockPos,
    /// The mode. Wire form: `Varuint32`.
    pub mode: u32,
    /// The needs redstone. Wire form: `Bool`.
    pub needs_redstone: bool,
    /// The conditional. Wire form: `Bool`.
    pub conditional: bool,
    /// The minecart entity runtime ID. Wire form: `ActorRuntimeID`.
    pub minecart_entity_runtime_id: u64,
    /// The command. Wire form: `String`.
    pub command: String,
    /// The last output. Wire form: `String`.
    pub last_output: String,
    /// The name. Wire form: `String`.
    pub name: String,
    /// The filtered name. Wire form: `String`.
    pub filtered_name: String,
    /// The should track output. Wire form: `Bool`.
    pub should_track_output: bool,
    /// The tick delay. Wire form: `Uint32`.
    pub tick_delay: u32,
    /// The execute on first tick. Wire form: `Bool`.
    pub execute_on_first_tick: bool,
}

impl Codec for CommandBlockUpdate {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self {
            block: r.bool()?,
            ..Self::default()
        };
        if pk.block {
            pk.position = r.block_pos()?;
            pk.mode = r.varuint32()?;
            pk.needs_redstone = r.bool()?;
            pk.conditional = r.bool()?;
        } else {
            pk.minecart_entity_runtime_id = r.actor_runtime_id()?;
        }
        pk.command = r.string()?;
        pk.last_output = r.string()?;
        pk.name = r.string()?;
        pk.filtered_name = r.string()?;
        pk.should_track_output = r.bool()?;
        pk.tick_delay = r.uint32()?;
        pk.execute_on_first_tick = r.bool()?;
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.bool(self.block);
        if self.block {
            w.block_pos(self.position);
            w.varuint32(self.mode);
            w.bool(self.needs_redstone);
            w.bool(self.conditional);
        } else {
            w.actor_runtime_id(self.minecart_entity_runtime_id);
        }
        w.string(&self.command)?;
        w.string(&self.last_output)?;
        w.string(&self.name)?;
        w.string(&self.filtered_name)?;
        w.bool(self.should_track_output);
        w.uint32(self.tick_delay);
        w.bool(self.execute_on_first_tick);
        Ok(())
    }
}

/// Packet `packet.CommandOutput` (ID 79), sent by the server.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct CommandOutput {
    /// The command origin.
    pub command_origin: CommandOrigin,
    /// The output type.
    pub output_type: u8,
    /// The success count. Wire form: `Uint32`.
    pub success_count: u32,
    /// The output messages. Wire form: a list after a `varuint32` count.
    pub output_messages: Vec<CommandOutputMessage>,
    /// The data set. Wire form: a bool, then the value when it is set.
    pub data_set: Option<String>,
}

impl Codec for CommandOutput {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self::default();
        super::types::decode_command_origin_data(r, &mut pk.command_origin)?;
        let output_type_str: String = r.string()?;
        pk.output_type = command_output_type_from_string(&output_type_str)?;
        pk.success_count = r.uint32()?;
        pk.output_messages = r.list_varuint32(CommandOutputMessage::decode)?;
        pk.data_set = if r.bool()? { Some(r.string()?) } else { None };
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        super::types::encode_command_origin_data(w, &self.command_origin)?;
        let output_type_str: &str = command_output_type_to_string(self.output_type);
        w.string(output_type_str)?;
        command_output_type_from_string(output_type_str)?;
        w.uint32(self.success_count);
        w.varuint32(length(self.output_messages.len())?);
        for v in &self.output_messages {
            v.encode(w)?;
        }
        w.bool(self.data_set.is_some());
        if let Some(v) = &self.data_set {
            w.string(v)?;
        }
        Ok(())
    }
}

