/// Packet `packet.InventoryTransaction` (ID 30), sent by the client and the server.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct InventoryTransaction {
    /// The legacy request ID. Wire form: `Varint32`.
    pub legacy_request_id: i32,
    /// The legacy set item slots. Wire form: a list after a `varuint32` count.
    pub legacy_set_item_slots: Vec<LegacySetItemSlot>,
    /// The actions. Wire form: a list after a `varuint32` count.
    pub actions: Vec<InventoryAction>,
    /// The transaction data. Wire form: `TransactionDataType`.
    pub transaction_data: InventoryTransactionData,
}

impl Codec for InventoryTransaction {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self {
            legacy_request_id: r.varint32()?,
            ..Self::default()
        };
        let has_legacy: bool = r.bool()?;
        if has_legacy {
            pk.legacy_set_item_slots = r.list_varuint32(LegacySetItemSlot::decode)?;
        }
        pk.transaction_data = r.transaction_data_type()?;
        pk.actions = r.list_varuint32(InventoryAction::decode)?;
        pk.transaction_data = pk.transaction_data.decode_variant(r)?;
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.varint32(self.legacy_request_id);
        let has_legacy: bool =
            (self.legacy_request_id < (-1)) && ((self.legacy_request_id & 1) == 0);
        w.bool(has_legacy);
        if has_legacy {
            w.varuint32(length(self.legacy_set_item_slots.len())?);
            for v in &self.legacy_set_item_slots {
                v.encode(w)?;
            }
        }
        w.transaction_data_type(&self.transaction_data);
        w.varuint32(length(self.actions.len())?);
        for v in &self.actions {
            v.encode(w)?;
        }
        self.transaction_data.encode_variant(w)?;
        Ok(())
    }
}

