/// Packet `packet.NetworkChunkPublisherUpdate` (ID 121), sent by the server.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct NetworkChunkPublisherUpdate {
    /// The position. Wire form: `BlockPos`.
    pub position: BlockPos,
    /// The radius. Wire form: `Varuint32`.
    pub radius: u32,
    /// The saved chunks. Mojang limit: 9216 elements.
    pub saved_chunks: Vec<ChunkPos>,
}

impl Codec for NetworkChunkPublisherUpdate {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self {
            position: r.block_pos()?,
            radius: r.varuint32()?,
            ..Self::default()
        };
        let count: u32 = r.uint32()?;
        if count > 9216 {
            return Err(Error::InvalidValue {
                field: "savedChunks",
                reason: "saved chunks exceeds maximum length of 9216 chunk positions",
            });
        }
        pk.saved_chunks = r.list_max(u64::from(count), 9216, Reader::chunk_pos)?;
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.block_pos(self.position);
        w.varuint32(self.radius);
        let count: u32 = super::types::go_usize_to_u32(self.saved_chunks.len());
        w.uint32(count);
        if count > 9216 {
            return Err(Error::InvalidValue {
                field: "savedChunks",
                reason: "saved chunks exceeds maximum length of 9216 chunk positions",
            });
        }
        if self.saved_chunks.len() != usize::try_from(count).map_err(|_| Error::Size)?
            || self.saved_chunks.len() > 9216
        {
            return Err(Error::Size);
        }
        for &v in &self.saved_chunks {
            w.chunk_pos(v);
        }
        Ok(())
    }
}

