/// Packet `packet.SetScoreboardIdentity` (ID 112), sent by the server.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct SetScoreboardIdentity {
    /// The action type. Wire form: `Uint8`.
    pub action_type: u8,
    /// The entries. Wire form: a list after a `varuint32` count.
    pub entries: Vec<ScoreboardIdentityEntry>,
}

impl Codec for SetScoreboardIdentity {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self {
            action_type: r.uint8()?,
            ..Self::default()
        };
        if (pk.action_type != 0) && (pk.action_type != 1) {
            return Err(Error::UnknownEnum {
                name: "scoreboard identity action type",
                value: i64::from(pk.action_type),
            });
        }
        pk.entries = r.list_varuint32(ScoreboardIdentityEntry::decode)?;
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.uint8(self.action_type);
        if (self.action_type != 0) && (self.action_type != 1) {
            return Err(Error::UnknownEnum {
                name: "scoreboard identity action type",
                value: i64::from(self.action_type),
            });
        }
        w.varuint32(length(self.entries.len())?);
        for v in &self.entries {
            v.encode(w)?;
        }
        Ok(())
    }
}

