/// Packet `packet.Text` (ID 9), sent by the client and the server.
#[derive(Debug, Clone, PartialEq, Default)]
#[expect(
    clippy::struct_field_names,
    reason = "consistency: field names mirror gophertunnel"
)]
pub struct Text {
    /// The text type. Wire form: `Uint8`. Values: [`TextType`](super::consts::TextType).
    pub text_type: u8,
    /// The needs translation. Wire form: `Bool`.
    pub needs_translation: bool,
    /// The source name. Wire form: `String`. Mojang limit: 256 bytes.
    pub source_name: String,
    /// The message. Wire form: `String`. Mojang limit: 65536 bytes.
    pub message: String,
    /// The parameters. Wire form: a list after a `varuint32` count. Mojang limit: 4 elements.
    pub parameters: Vec<String>,
    /// The XUID. Wire form: `String`. Mojang limit: 64 bytes.
    pub xuid: String,
    /// The platform chat ID. Wire form: `String`. Mojang limit: 256 bytes.
    pub platform_chat_id: String,
    /// The filtered message. Wire form: a bool, then the value when it is set. Mojang limit: 65536 bytes.
    pub filtered_message: Option<String>,
}

impl Codec for Text {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut pk = Self {
            needs_translation: r.bool()?,
            ..Self::default()
        };
        r.uint8()?;
        pk.text_type = r.uint8()?;
        match pk.text_type {
            1 | 7 | 8 => {
                pk.source_name = r.string_max(256)?;
                if pk.source_name.len() > 256 {
                    return Err(Error::InvalidValue {
                        field: "source name",
                        reason: "string too long",
                    });
                }
                pk.message = r.string_max(65_536)?;
            }
            0 | 5 | 6 | 9..=11 => {
                pk.message = r.string_max(65_536)?;
            }
            2..=4 => {
                pk.message = r.string_max(65_536)?;
                pk.parameters = r.list_varuint32_max(4, Reader::string)?;
                if pk.parameters.len() > 4 {
                    return Err(Error::InvalidValue {
                        field: "parameters",
                        reason: "too many parameters",
                    });
                }
            }
            _ => {}
        }
        if pk.message.is_empty() {
            return Err(Error::InvalidValue {
                field: "message",
                reason: "string cannot be empty",
            });
        }
        if pk.message.len() > 65_536 {
            return Err(Error::InvalidValue {
                field: "message",
                reason: "string too long",
            });
        }
        pk.xuid = r.string_max(64)?;
        if pk.xuid.len() > 64 {
            return Err(Error::InvalidValue {
                field: "XUID",
                reason: "string too long",
            });
        }
        pk.platform_chat_id = r.string_max(256)?;
        if pk.platform_chat_id.len() > 256 {
            return Err(Error::InvalidValue {
                field: "platform chat ID",
                reason: "string too long",
            });
        }
        pk.filtered_message = if r.bool()? {
            Some(r.string_max(65_536)?)
        } else {
            None
        };
        if let Some(filtered_message) = &pk.filtered_message
            && filtered_message.len() > 65_536
        {
            return Err(Error::InvalidValue {
                field: "filtered message",
                reason: "string too long",
            });
        }
        Ok(pk)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.bool(self.needs_translation);
        let category_type: u8 = match self.text_type {
            0 | 5 | 6 | 9..=11 => 0,
            1 | 7 | 8 => 1,
            _ => 2,
        };
        w.uint8(category_type);
        w.uint8(self.text_type);
        match self.text_type {
            1 | 7 | 8 => {
                w.string_max(&self.source_name, 256)?;
                if self.source_name.len() > 256 {
                    return Err(Error::InvalidValue {
                        field: "source name",
                        reason: "string too long",
                    });
                }
                w.string_max(&self.message, 65_536)?;
            }
            0 | 5 | 6 | 9..=11 => {
                w.string_max(&self.message, 65_536)?;
            }
            2..=4 => {
                w.string_max(&self.message, 65_536)?;
                w.varuint32(length_max(self.parameters.len(), 4)?);
                for v in &self.parameters {
                    w.string(v)?;
                }
                if self.parameters.len() > 4 {
                    return Err(Error::InvalidValue {
                        field: "parameters",
                        reason: "too many parameters",
                    });
                }
            }
            _ => {}
        }
        if self.message.is_empty() {
            return Err(Error::InvalidValue {
                field: "message",
                reason: "string cannot be empty",
            });
        }
        if self.message.len() > 65_536 {
            return Err(Error::InvalidValue {
                field: "message",
                reason: "string too long",
            });
        }
        w.string_max(&self.xuid, 64)?;
        if self.xuid.len() > 64 {
            return Err(Error::InvalidValue {
                field: "XUID",
                reason: "string too long",
            });
        }
        w.string_max(&self.platform_chat_id, 256)?;
        if self.platform_chat_id.len() > 256 {
            return Err(Error::InvalidValue {
                field: "platform chat ID",
                reason: "string too long",
            });
        }
        w.bool(self.filtered_message.is_some());
        if let Some(v) = &self.filtered_message {
            w.string_max(v, 65_536)?;
        }
        if let Some(filtered_message) = &self.filtered_message
            && filtered_message.len() > 65_536
        {
            return Err(Error::InvalidValue {
                field: "filtered message",
                reason: "string too long",
            });
        }
        Ok(())
    }
}

